        _t_records188 = [_t_n188 for _t_n188 in _ast188.walk(_t_tree188)
                         if isinstance(_t_n188, _ast188.Call)
                         and getattr(_t_n188.func, "attr", "") == "record"]
        if not _t_records188:
            _t_silent188.append(_t_f188.name)

